import re
import urllib.parse
import requests
import json

def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s<>"\'{}|\\^`\[\]]+'
    raw_urls = re.findall(url_pattern, myString)

    domains = set()
    for raw in raw_urls:
        try:
            parsed = urllib.parse.urlparse(raw)
            host = parsed.netloc.split(':')[0]
            if host:
                domains.add(host)
        except Exception:
            continue

    result = {}
    for domain in domains:
        try:
            url = f"https://ipinfo.io/{domain}?token={API_KEY}"
            resp = requests.get(url, timeout=10)
            if resp.status_code != 200:
                result[domain] = None
            else:
                data = resp.json()
                result[domain] = data
        except Exception:
            result[domain] = None

    return result

