import requests
import os
import zipfile
from io import BytesIO

def task_func(url, destination_directory, headers=None):
    if not url or not isinstance(url, str):
        raise ValueError("URL must be a non-empty string.")
    if not destination_directory or not isinstance(destination_directory, str):
        raise ValueError("destination_directory must be a non-empty string.")

    is_internal = '.internal.' in url
    verify_cert = False if is_internal else True

    try:
        response = requests.get(url, stream=True, headers=headers, verify=verify_cert)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download zip from {url}: {e}")

    try:
        zip_buffer = BytesIO(response.content)
        with zipfile.ZipFile(zip_buffer) as zf:
            if zipfile.is_zipfile(zip_buffer) is False:
                raise ValueError("Downloaded content is not a valid zip file.")
            os.makedirs(destination_directory, exist_ok=True)
            zf.extractall(destination_directory)
            extracted_files = zf.namelist()
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {e}")
    except OSError as e:
        raise OSError(f"Failed to extract zip to {destination_directory}: {e}")

    return extracted_files

