import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt

HEADERS = {
    'accept': 'application/json'
}

def task_func(url, parameters):
    if not isinstance(url, str) or not url:
        raise Exception("Invalid URL provided.")
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
    except Exception as e:
        raise Exception(f"Failed to fetch data from URL: {e}")
    try:
        data = response.json()
    except (json.JSONDecodeError, ValueError) as e:
        raise Exception("Invalid JSON response from API.")
    if not data or (isinstance(data, list) and len(data) == 0):
        raise Exception("Empty data returned from API.")
    df = pd.DataFrame(data)
    if df.empty:
        raise Exception("DataFrame is empty after conversion.")
    numeric_df = df.select_dtypes(include='number')
    if numeric_df.empty:
        raise Exception("No numeric columns available for correlation heatmap.")
    corr = numeric_df.corr()
    fig, ax = plt.subplots()
    sns.heatmap(corr, annot=True, ax=ax)
    plt.show()
    return (df, ax)

